#pragma once
#include <stdint.h>

/*
 * wlanlink.h - W3a, `--wlan-link[=N]` (implies --wlan-probe; gs101 only; NOT combinable with --wlan-en / --wlan-iso): the long power-up chain S00..S27 of docs/research/29 as ONE table-driven,
 * audited interpreter. The steps are the rows of soc/google/gs101/wlan_seq.json (generated by tools/gen_wlan_seq.py from the Google sources, turned into out/wlan_seq.h by tools/boards.py with the
 * table hash); wlan_link_run() executes steps 0..N (N = WLAN_LINK_N, default WLAN_SEQ_DEFAULT_N = the last step BEFORE the PERST release; build.sh --wlan-link=N), in order, stops at the first
 * failure, and ALWAYS runs the teardown rows of the steps that were started, in the table order (PERST low, LTSSM off, WLAN_EN low, soft power reset, PHY power-down, isolation clear LAST, pins to
 * input). A step number without rows refuses the whole run before the first write; S22 (RC setup, UNKNOWN: runtime values) is a documented skip with one 0 us delay row so S23 is reachable.
 * Output (con_str "WLAN"): `LINK table sha=.. rows=.. N=..`, per step `LINK Sxx start` (+ pstore checkpoint), `LINK Sxx ok rows=n rd=0x..` or `LINK Sxx timeout|fault|refused row=i rd=0x..`,
 * per teardown row failures `LINK Txx fault`, and `LINK summary reached=Sxx stopped=<none|timeout|fault|refused> at=Sxx row=i restore=<ok|FAILED>`.
 * The only writer is w32(idx, tear) (wlanlink.c): it reads the row from the const table itself, re-checks pa/mask/value against an independent allowlist (blocks, offsets, pin masks) and holds the
 * single try_write32 call site. The two SMC steps go through wlan_link_iso_set/clear (wlansmc.c), nothing else issues an SMC.
 */
int try_read32(uintptr_t address, uint32_t *value);
int try_write32(uintptr_t address, uint32_t value);
uint64_t touch_ticks(void);
int wlan_link_run(void);
